const [active, setActive] = useState<{ label: string; size: number | null } | null>(null);

<BubbleChart
  data={teams}
  xDataKey="efficiency"
  yDataKey="performance"
  sizeKey="people"
  labelKey="team"
  sizeRange={[14, 30]}
  aspectRatio={1.4}
  onActivePointChange={(point) =>
    setActive(point ? { label: point.label, size: point.size } : null)
  }
>
  <BubbleChart.Header
    value={active ? `Team ${active.label}` : '8 teams'}
    caption={
      active && active.size !== null ? `${active.size} people` : 'Circle area is team size'
    }
  />
  <BubbleChart.Grid />
  <BubbleChart.Bubbles />
  <BubbleChart.Labels />
  <BubbleChart.XAxis />
  <BubbleChart.YAxis />
  <BubbleChart.Tooltip />
</BubbleChart>
